using System;
using System.Runtime.InteropServices;

namespace Njulf.Rendering.Resources;

/// <summary>
/// Reference RGB coefficient data for the Hosek-Wilkie analytic sky model.
/// Copyright (c) 2012-2013 Lukas Hosek and Alexander Wilkie; 3-clause BSD.
/// See the repository THIRD-PARTY-NOTICES.txt for the complete license.
/// </summary>
internal static class HosekWilkieRgbData
{
    private const string ParamsRBase64 = "";

    private const string ParamsGBase64 = "";

    private const string ParamsBBase64 = "";

    private const string RadiancesRBase64 = "";

    private const string RadiancesGBase64 = "";

    private const string RadiancesBBase64 = "";

    internal static float[] ParamsR { get; } = Decode(ParamsRBase64, 1_080);
    internal static float[] ParamsG { get; } = Decode(ParamsGBase64, 1_080);
    internal static float[] ParamsB { get; } = Decode(ParamsBBase64, 1_080);
    internal static float[] RadiancesR { get; } = Decode(RadiancesRBase64, 120);
    internal static float[] RadiancesG { get; } = Decode(RadiancesGBase64, 120);
    internal static float[] RadiancesB { get; } = Decode(RadiancesBBase64, 120);

    private static float[] Decode(string base64, int expectedFloatCount)
    {
        byte[] bytes = Convert.FromBase64String(base64);
        if (bytes.Length != checked(expectedFloatCount * sizeof(float)))
            throw new InvalidOperationException("The embedded Hosek-Wilkie dataset has an invalid length.");

        if (!BitConverter.IsLittleEndian)
        {
            for (int offset = 0; offset < bytes.Length; offset += sizeof(float))
                Array.Reverse(bytes, offset, sizeof(float));
        }

        return MemoryMarshal.Cast<byte, float>(bytes).ToArray();
    }
}

